using System;
using System.Linq;
using System.Reflection;
using System.Text.RegularExpressions;
using HarmonyLib;

namespace SunlessSkiesCN.Shared
{
    // Match only the complete challenge tooltip generated by ChallengePresenter.
    // Translate when displayed, retaining the bound original and challenge data.
    public static class ChallengeTooltipLocalization
    {
        public const string Template = "Your {value1} gives you a <b>{value2}% chance of success</b>";
        static readonly Regex Source = new Regex(@"\AYour (?<name>[^<>\r\n]+) gives you a <b>(?<chance>[0-9]+)% chance of success</b>\z", RegexOptions.CultureInvariant);
        static readonly Regex Slots = new Regex(@"\{value[^{}]*\}", RegexOptions.CultureInvariant);
        static readonly Regex Tags = new Regex(@"<[^>]*>", RegexOptions.CultureInvariant);
        static Func<string,string> lookup;
        static Func<bool> enabled;
        static Action<string> log;
        static int traces;
        public static void Install(Assembly game, Func<string,string> translate, Func<bool> active, Action<string> logger)
        {
            var presenter = game.GetType("Skyless.Assets.Code.Skyless.UI.Presenters.Generic.TooltipPresenter", true);
            var show = presenter.GetMethods(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance)
                .Single(m => m.Name == "ShowInternal" && m.ReturnType == typeof(void) && m.GetParameters().Length == 5 &&
                    m.GetParameters()[0].ParameterType == typeof(string) && m.GetParameters()[1].ParameterType == typeof(string));
            lookup = translate; enabled = active; log = logger;
            var harmony = new Harmony("githongwu.sunlessskies.challenge-tooltip");
            try { harmony.Patch(show, prefix: new HarmonyMethod(typeof(ChallengeTooltipLocalization), "Prefix")); }
            catch { harmony.UnpatchSelf(); throw; }
            log("Challenge tooltip localization ready: TooltipPresenter.ShowInternal.");
        }
        static void Prefix(ref string __1)
        {
            try
            {
                if (!enabled()) return;
                string translated = Localize(__1, lookup);
                if (translated != __1 && traces++ < 4) log("Challenge tooltip translated.");
                __1 = translated;
            }
            catch (Exception e) { if (traces++ < 4) log("Challenge tooltip fallback: " + e.Message); }
        }
        public static string Localize(string text, Func<string,string> translate)
        {
            if (String.IsNullOrEmpty(text)) return text;
            Match match = Source.Match(text);
            if (!match.Success) return text;
            string translated = translate(Template);
            if (String.IsNullOrEmpty(translated) || translated == Template) return text;
            var slots = Slots.Matches(translated).Cast<Match>().Select(m => m.Value).OrderBy(s => s).ToArray();
            if (!slots.SequenceEqual(new[] { "{value1}", "{value2}" })) return text;
            if (!Tags.Matches(translated).Cast<Match>().Select(m => m.Value).SequenceEqual(new[] { "<b>", "</b>" })) return text;
            // Keep the percentage and its bold styling together.
            if (!translated.Contains("<b>{value2}%")) return text;
            string name = match.Groups["name"].Value;
            string localizedName = translate(name);
            if (String.IsNullOrEmpty(localizedName) || localizedName.IndexOfAny(new[] {'<', '>', '{', '}', '\r', '\n'}) >= 0) localizedName = name;
            // One substitution pass prevents text from an inserted name being
            // interpreted as another placeholder. Numeric spelling is unchanged.
            return Slots.Replace(translated, m => m.Value == "{value1}" ? localizedName : match.Groups["chance"].Value);
        }
    }
}
